/* Browser speech recognition: no app API key; the browser provider may process audio online. */
(function(root){let active=null;let cleanup=()=>{};
function stop(){if(active){try{active.abort()}catch{}active=null}cleanup();cleanup=()=>{}}
function bind(scope=document){scope.querySelectorAll('[data-voice-for]').forEach(button=>{let supported=!!(root.SpeechRecognition||root.webkitSpeechRecognition);let status=button.parentElement.querySelector('[data-voice-status]');if(!supported){button.disabled=true;button.textContent='Dictation unavailable';status.textContent='Type here, or use your keyboard’s dictation. Browser dictation is not supported in this browser.';return}
button.onclick=()=>{if(active){stop();return}let target=document.querySelector(button.dataset.voiceFor);if(!target)return;let provider=new (root.SpeechRecognition||root.webkitSpeechRecognition)(),base=target.value.trim(),finals='';active=provider;provider.lang='en-US';provider.interimResults=true;provider.continuous=true;let stamp=Date.now(),limit=setTimeout(()=>provider.stop(),90000);cleanup=()=>{clearTimeout(limit);button.textContent='Use voice';button.classList.remove('listening');button.setAttribute('aria-pressed','false')};provider.onstart=()=>{button.textContent='Stop dictation';button.classList.add('listening');button.setAttribute('aria-pressed','true');status.textContent='Listening… Your words will appear below. Stop to review them.'};provider.onresult=e=>{let interim='';finals='';for(let i=0;i<e.results.length;i++){if(e.results[i].isFinal)finals+=e.results[i][0].transcript+' ';else interim+=e.results[i][0].transcript}target.value=[base,finals.trim(),interim.trim()].filter(Boolean).join(' ');target.dispatchEvent(new Event('input',{bubbles:true}));status.textContent='Transcribing… '+Math.floor((Date.now()-stamp)/1000)+' sec. Stop when ready.'};provider.onerror=e=>{status.textContent=({'not-allowed':'Microphone access was denied. Allow it in browser settings, or type your answer.','audio-capture':'No microphone was found. Check your input device, or type here.','network':'The browser’s speech service could not connect. Try again or type here.','no-speech':'No speech was detected. Try again or type here.','service-not-allowed':'This browser cannot use its speech service here. Try Chrome or Safari, or use keyboard dictation.'})[e.error]||'Dictation stopped. You can edit the text or try again.'};provider.onend=()=>{if(active===provider){active=null;cleanup();cleanup=()=>{};if(status.textContent.startsWith('Listening')||status.textContent.startsWith('Transcribing'))status.textContent='Dictation stopped. Review and edit your words before continuing.'}};try{provider.start()}catch{status.textContent='Could not start dictation. Try again or type here.';stop()}};})}
root.VoiceInput={bind,stop};
})(window);
